/**
 * HRNexus Bootstrap Admin Dashboard v4.0 — JS Bundle
 * Built: 2026-09-16 | development
 */
(function(window, document) {
'use strict';


// ── Safe localStorage wrapper (works under file:// and restricted origins) ──
var store = {
  get: function(k, def) {
    try { var v = localStorage.getItem(k); return v !== null ? v : (def !== undefined ? def : null); }
    catch(e) { return def !== undefined ? def : null; }
  },
  set: function(k, v) { try { localStorage.setItem(k, v); } catch(e) {} },
};

// ── theme.js ──────────────────────────────────────────────
/**
 * theme.js — Theme & dark-mode manager
 * NOTE: 'store' is injected by bundle.js before this file
 */
const ThemeManager = {
  init() {
    this.apply(store.get('hr-theme', 'light'));
    const preset = store.get('hr-color-theme', 'default');
    if (preset && preset !== 'default') this.applyPreset(preset);

    document.addEventListener('click', e => {
      const btn = e.target?.closest?.('[data-theme-toggle]');
      if (btn) {
        const cur = document.documentElement.getAttribute('data-bs-theme') || 'light';
        this.apply(cur === 'dark' ? 'light' : 'dark');
      }
      const presetEl = e.target?.closest?.('[data-theme-preset]');
      if (presetEl) this.applyPreset(presetEl.dataset.themePreset);
    });
  },

  apply(mode) {
    document.documentElement.setAttribute('data-bs-theme', mode);
    store.set('hr-theme', mode);
    document.querySelectorAll('.theme-icon-light').forEach(i => i.style.display = mode === 'dark'  ? 'none' : '');
    document.querySelectorAll('.theme-icon-dark').forEach(i  => i.style.display = mode === 'light' ? 'none' : '');
  },

  applyPreset(name) {
    document.documentElement.classList.remove('theme-midnight', 'theme-rose', 'theme-forest', 'theme-sunset');
    if (name && name !== 'default') document.documentElement.classList.add('theme-' + name);
    store.set('hr-color-theme', name || 'default');
  },
};


// ── sidebar.js ────────────────────────────────────────────
/**
 * sidebar.js — Sidebar navigation: toggle, groups, active state, mobile
 */
const SidebarManager = {
  sidebar:  null,
  main:     null,
  backdrop: null,
  popup:    null,
  popupOpenBtn: null,

  init() {
    this.sidebar  = document.querySelector('.sidebar');
    this.main     = document.querySelector('.main-content');
    this.backdrop = document.querySelector('.mobile-backdrop');
    this.popup    = document.getElementById('sb-main-popup');
    if (!this.sidebar) return;

    // Restore collapsed state
    if (store.get('hr-sidebar-collapsed', '0') === '1') this._setCollapsed(true, true);

    // Desktop hamburger toggle
    document.querySelector('[data-sidebar-toggle]')
      ?.addEventListener('click', () => this.toggle());

    // Mobile hamburger
    document.querySelectorAll('[data-sidebar-mobile-toggle]')
      .forEach(btn => btn.addEventListener('click', () => this.mobileToggle()));

    // Backdrop closes mobile drawer
    this.backdrop?.addEventListener('click', () => this.mobileClose());

    // Group expand / collapse — bind directly to each button
    this.sidebar.querySelectorAll('.nav-group-hd').forEach(btn => {
      btn.addEventListener('click', e => {
        e.preventDefault();
        e.stopPropagation();
        this._toggleGroup(btn);
      });
    });

    // ESC closes mobile + any open flyout
    document.addEventListener('keydown', e => {
      if (e.key === 'Escape') {
        this.mobileClose();
        this._closeFlyout();
      }
    });

    // Click elsewhere closes an open flyout
    document.addEventListener('click', e => {
      if (this.popupOpenBtn && this.popup &&
          !this.popup.contains(e.target) && !this.popupOpenBtn.contains(e.target)) {
        this._closeFlyout();
      }
    });
    window.addEventListener('resize', () => this._closeFlyout());

    this._markActive();
  },

  toggle() {
    const collapsed = this.sidebar.classList.toggle('collapsed');
    this.main?.classList.toggle('sidebar-collapsed', collapsed);
    store.set('hr-sidebar-collapsed', collapsed ? '1' : '0');
    this._closeFlyout();
  },

  _setCollapsed(yes, silent = false) {
    if (silent) this.sidebar.style.transition = 'none';
    this.sidebar.classList.toggle('collapsed', yes);
    this.main?.classList.toggle('sidebar-collapsed', yes);
    if (silent) setTimeout(() => { this.sidebar.style.transition = ''; }, 50);
  },

  mobileToggle() {
    const open = this.sidebar.classList.toggle('mobile-open');
    if (this.backdrop) this.backdrop.style.display = open ? 'block' : 'none';
    document.body.style.overflow = open ? 'hidden' : '';
  },

  mobileClose() {
    this.sidebar.classList.remove('mobile-open');
    if (this.backdrop) this.backdrop.style.display = 'none';
    document.body.style.overflow = '';
  },

  /* ── Group toggle ─────────────────────────────────────────────────────
   * HTML structure:
   *   <div class="nav-li">              ← btn.parentElement
   *     <button class="nav-group-hd">  ← btn
   *   </div>
   *   <div class="nav-group-body">     ← navLi.nextElementSibling
   *
   * Single-open accordion: opening one group now closes any other open
   * group first, instead of letting multiple stay open independently.
   *
   * Collapsed sidebar: clicking a group icon pops its submenu out to the
   * right as a flyout instead of expanding inline (there's no room for
   * labels when collapsed, and .sidebar's overflow:hidden would clip an
   * inline expansion anyway).
   * ─────────────────────────────────────────────────────────────────── */
  _toggleGroup(btn) {
    const navLi = btn.parentElement;           // the wrapping .nav-li
    const body  = navLi?.nextElementSibling;   // the .nav-group-body
    if (!body || !body.classList.contains('nav-group-body')) return;

    if (this.sidebar.classList.contains('collapsed')) {
      if (this.popupOpenBtn === btn) { this._closeFlyout(); return; }
      this._closeFlyout();
      this._openFlyout(btn, body);
      return;
    }

    const willOpen = !body.classList.contains('open');

    this.sidebar.querySelectorAll('.nav-group-body.open').forEach(b => {
      if (b !== body) b.classList.remove('open');
    });
    this.sidebar.querySelectorAll('.nav-group-hd.active').forEach(h => {
      if (h !== btn) {
        h.classList.remove('active');
        h.setAttribute('aria-expanded', 'false');
        h.querySelector('.nav-chevron')?.classList.remove('open');
      }
    });

    body.classList.toggle('open', willOpen);
    btn.querySelector('.nav-chevron')?.classList.toggle('open', willOpen);
    btn.setAttribute('aria-expanded', String(willOpen));
    btn.classList.toggle('active', willOpen);
  },

  /* ── Flyout popup for the collapsed sidebar ─────────────────────────
   * Requires a <div id="sb-main-popup"> somewhere on the page. If a page
   * doesn't have one yet, this safely does nothing rather than erroring —
   * clicking a group icon while collapsed just won't show a flyout there,
   * same as the previous behaviour, until the element is added. */
  _closeFlyout() {
    if (!this.popup) return;
    this.popup.classList.remove('visible');
    this.popup.setAttribute('aria-hidden', 'true');
    if (this.popupOpenBtn) {
      this.popupOpenBtn.classList.remove('popup-open');
      this.popupOpenBtn.setAttribute('aria-expanded', 'false');
    }
    this.popupOpenBtn = null;
  },

  _openFlyout(btn, body) {
    if (!this.popup) return;
    const title = btn.querySelector('.nav-text')?.textContent?.trim() || '';
    const links = body.querySelectorAll('.nav-lnk');

    let html = title ? `<div class="popup-title">${title}</div>` : '';
    links.forEach(link => {
      // Clone each real sidebar link so the flyout always matches the
      // actual nav-group-body content (labels, hrefs, badges) rather than
      // duplicating it by hand and risking the two falling out of sync.
      const clone = link.cloneNode(true);
      clone.classList.remove('nav-child');
      html += clone.outerHTML;
    });
    this.popup.innerHTML = html;

    // Make it paint (invisibly) before measuring — offsetHeight reads 0
    // while display:none, which would silently break the overflow checks
    // below for icons near the bottom of the sidebar.
    this.popup.style.visibility = 'hidden';
    this.popup.classList.add('visible');
    const popupHeight = this.popup.offsetHeight;

    const rect = btn.getBoundingClientRect();
    this.popup.style.left = `${Math.round(rect.right + 8)}px`;

    const spaceBelow = window.innerHeight - rect.top - 16;
    const spaceAbove = rect.bottom - 16;
    if (popupHeight > spaceBelow && spaceAbove >= popupHeight) {
      // Not enough room to grow downward from the icon — flip to anchor
      // from its bottom edge and grow upward instead, so the whole
      // submenu stays on screen.
      this.popup.style.top = 'auto';
      this.popup.style.bottom = `${Math.round(window.innerHeight - rect.bottom)}px`;
    } else {
      this.popup.style.bottom = 'auto';
      const top = Math.round(rect.top);
      const maxTop = window.innerHeight - popupHeight - 16;
      this.popup.style.top = `${Math.max(8, Math.min(top, maxTop))}px`;
    }

    this.popup.style.visibility = '';
    this.popup.setAttribute('aria-hidden', 'false');
    btn.classList.add('popup-open');
    btn.setAttribute('aria-expanded', 'true');
    this.popupOpenBtn = btn;
  },

  /* ── Mark the current page link as active ───────────────────────────── */
  _markActive() {
    // Works for both server (pathname) and file:// (filename from path)
    const page = window.location.pathname.split('/').pop() || 'index.html';

    // Clear any stray active/open state first. Several pages have leftover
    // 'active'/'open' classes baked into their static HTML from template
    // copy-paste (a leftover default group left open, sometimes alongside
    // the correct one) — clearing everything up front means whatever the
    // static markup says, the sidebar always ends up showing the single,
    // correct group for the current page.
    this.sidebar.querySelectorAll('.nav-group-hd.active').forEach(btn => {
      btn.classList.remove('active');
      btn.setAttribute('aria-expanded', 'false');
      btn.querySelector('.nav-chevron')?.classList.remove('open');
    });
    this.sidebar.querySelectorAll('.nav-group-body.open').forEach(body => {
      body.classList.remove('open');
    });

    this.sidebar.querySelectorAll('.nav-lnk[href]').forEach(link => {
      const href = link.getAttribute('href').split('/').pop().split('?')[0].split('#')[0];
      const active = href === page || (page === '' && href === 'index.html');
      link.classList.toggle('active', active);

      if (active) {
        const groupBody = link.closest('.nav-group-body');
        if (groupBody) {
          groupBody.classList.add('open');
          const groupBtn = groupBody.previousElementSibling?.querySelector('.nav-group-hd');
          if (groupBtn) {
            groupBtn.querySelector('.nav-chevron')?.classList.add('open');
            groupBtn.setAttribute('aria-expanded', 'true');
            groupBtn.classList.add('active');
          }
        }
      }
    });
  },
};


// ── topbar.js ─────────────────────────────────────────────
/**
 * topbar.js — Notification & profile panels, search
 */
const TopbarManager = {
  init() {
    // Panel toggles (bell, profile avatar)
    document.addEventListener('click', e => {
      const trigger = e.target?.closest?.('[data-panel-toggle]');

      if (trigger) {
        e.stopPropagation();
        const panelId = trigger.dataset.panelToggle;
        const panel   = document.getElementById(panelId);
        if (!panel) return;

        // Close every other panel
        document.querySelectorAll('.hr-panel').forEach(p => {
          if (p.id !== panelId) p.style.display = 'none';
        });

        panel.style.display = panel.style.display === 'block' ? 'none' : 'block';
        return;
      }

      // Click anywhere outside → close all panels
      if (!e.target?.closest?.('.hr-panel') && !e.target?.closest?.('[data-panel-toggle]')) {
        document.querySelectorAll('.hr-panel').forEach(p => p.style.display = 'none');
      }
    });

    // ESC closes panels
    document.addEventListener('keydown', e => {
      if (e.key === 'Escape') {
        document.querySelectorAll('.hr-panel').forEach(p => p.style.display = 'none');
      }
    });
  },
};


// ── tooltip.js ────────────────────────────────────────────
/**
 * tooltip.js — Sidebar tooltips when collapsed
 */
const TooltipManager = {
  tip: null,

  init() {
    this.tip = Object.assign(document.createElement('div'), {
      className: 'hr-sidebar-tooltip',
    });
    document.body.appendChild(this.tip);

    document.addEventListener('mouseenter', e => {
      const el = e.target?.closest?.('[data-sidebar-tooltip]');
      if (!el || !document.querySelector('.sidebar.collapsed')) return;
      this.show(el, el.dataset.sidebarTooltip);
    }, true);

    document.addEventListener('mouseleave', e => {
      if (e.target?.closest?.('[data-sidebar-tooltip]')) this.hide();
    }, true);
  },

  show(el, label) {
    if (!label || !this.tip) return;
    const r = el.getBoundingClientRect();
    this.tip.textContent = label;
    Object.assign(this.tip.style, {
      left:      `${r.right + 10}px`,
      top:       `${r.top + r.height / 2}px`,
      transform: 'translateY(-50%)',
      opacity:   '1',
    });
  },

  hide() { if (this.tip) this.tip.style.opacity = '0'; },
};


// ── search.js ─────────────────────────────────────────────
/**
 * search.js — Live table search via [data-table-search]
 */
function initSearch() {
  document.querySelectorAll('[data-table-search]').forEach(input => {
    const tableId = input.dataset.tableSearch;
    const table   = tableId
      ? document.getElementById(tableId)
      : (input.closest('.card-hr') || input.closest('.card') || document.body).querySelector('table');
    if (!table) return;

    input.addEventListener('input', () => {
      const q = input.value.toLowerCase().trim();
      table.querySelectorAll('tbody tr').forEach(row => {
        row.style.display = !q || row.textContent.toLowerCase().includes(q) ? '' : 'none';
      });
    });
  });
}


// ── charts.js ────────────────────────────────────────
/**
 * charts.js — ApexCharts integration (CDN, optional)
 */
function initCharts() {
  if (typeof window.ApexCharts === 'undefined') return;

  const isDark = document.documentElement.getAttribute('data-bs-theme') === 'dark';

  // Department bar chart
  const barEl = document.getElementById('deptChart');
  if (barEl && !barEl._chart) {
    barEl._chart = new window.ApexCharts(barEl, {
      chart:  { type: 'bar', height: 240, toolbar: { show: false }, background: 'transparent' },
      theme:  { mode: isDark ? 'dark' : 'light' },
      colors: ['#4F6EF7'],
      plotOptions: { bar: { borderRadius: 6, columnWidth: '55%' } },
      dataLabels: { enabled: false },
      series: [{ name: 'Employees', data: [68, 42, 35, 28, 22, 18] }],
      xaxis: {
        categories: ['Engineering', 'Product', 'Sales', 'Marketing', 'HR', 'Finance'],
        axisBorder: { show: false },
        axisTicks:  { show: false },
      },
      grid: { borderColor: isDark ? '#1A2035' : '#E4E6F0', strokeDashArray: 4 },
    });
    barEl._chart.render();
  }

  // Attendance donut chart
  const donutEl = document.getElementById('attendanceDonut');
  if (donutEl && !donutEl._chart) {
    donutEl._chart = new window.ApexCharts(donutEl, {
      chart:  { type: 'donut', height: 220, background: 'transparent' },
      colors: ['#10B981', '#F59E0B', '#EF4444'],
      series: [261, 18, 5],
      labels: ['Present', 'Leave', 'Absent'],
      dataLabels: { enabled: false },
      legend: { position: 'bottom', fontSize: '12px' },
      plotOptions: { pie: { donut: { size: '70%' } } },
    });
    donutEl._chart.render();
  }
}


// ── tables.js ────────────────────────────────────────
/**
 * tables.js — Click-to-sort on table[data-sortable] th[data-sort]
 */
function initTables() {
  document.querySelectorAll('table[data-sortable]').forEach(table => {
    table.querySelectorAll('th[data-sort]').forEach((th, colIdx) => {
      th.style.cursor = 'pointer';
      th.title = 'Click to sort';
      let asc = true;

      th.addEventListener('click', () => {
        const tbody = table.querySelector('tbody');
        if (!tbody) return;

        const rows = [...tbody.querySelectorAll('tr')];
        const num  = s => parseFloat(s.replace(/[^0-9.-]/g, ''));

        rows.sort((a, b) => {
          const av = (a.cells[colIdx]?.textContent || '').trim();
          const bv = (b.cells[colIdx]?.textContent || '').trim();
          const an = num(av), bn = num(bv);
          if (!isNaN(an) && !isNaN(bn)) return asc ? an - bn : bn - an;
          return asc ? av.localeCompare(bv) : bv.localeCompare(av);
        });

        rows.forEach(r => tbody.appendChild(r));
        table.querySelectorAll('th[data-sort]').forEach(h => h.removeAttribute('data-sort-dir'));
        th.setAttribute('data-sort-dir', asc ? 'asc' : 'desc');
        asc = !asc;
      });
    });
  });
}


// ── kanban.js ────────────────────────────────────────
/**
 * kanban.js — HTML5 drag-and-drop kanban board
 */
function initKanban() {
  const board = document.querySelector('.kanban-board');
  if (!board) return;

  let dragSrc = null;

  // Make cards draggable
  board.querySelectorAll('.kcard').forEach(card => {
    card.setAttribute('draggable', 'true');

    card.addEventListener('dragstart', e => {
      dragSrc = card;
      e.dataTransfer.effectAllowed = 'move';
      e.dataTransfer.setData('text/plain', '');
      setTimeout(() => { card.style.opacity = '0.4'; }, 0);
    });

    card.addEventListener('dragend', () => {
      card.style.opacity = '';
      dragSrc = null;
    });
  });

  // Column drop targets
  board.querySelectorAll('.kanban-col').forEach(col => {
    col.addEventListener('dragover', e => {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      col.style.outline    = '2px dashed var(--color-primary)';
      col.style.background = 'rgba(79,110,247,0.04)';
    });

    col.addEventListener('dragleave', () => {
      col.style.outline    = '';
      col.style.background = '';
    });

    col.addEventListener('drop', e => {
      e.preventDefault();
      col.style.outline    = '';
      col.style.background = '';

      if (dragSrc && !col.contains(dragSrc)) {
        col.appendChild(dragSrc);
        // Update column card counts
        board.querySelectorAll('.kanban-col').forEach(c => {
          const badge = c.querySelector('.kanban-count');
          if (badge) badge.textContent = c.querySelectorAll('.kcard').length;
        });
      }
    });
  });
}


// ── main.js ─────────────────────────────────────────────────────
/**
 * main.js — Single init entry point
 */
function initBootstrapComponents() {
  if (typeof window.bootstrap === 'undefined') return;
  document.querySelectorAll('[data-bs-toggle="tooltip"]')
    .forEach(el => { try { new window.bootstrap.Tooltip(el); } catch {} });
  document.querySelectorAll('[data-bs-toggle="popover"]')
    .forEach(el => { try { new window.bootstrap.Popover(el); } catch {} });
}

function initScrollTop() {
  const btn = document.getElementById('scrollTopBtn');
  const pc  = document.querySelector('.page-content');
  if (!btn || !pc) return;
  pc.addEventListener('scroll', () => {
    btn.style.display = pc.scrollTop > 300 ? 'flex' : 'none';
  });
  btn.addEventListener('click', () => pc.scrollTo({ top: 0, behavior: 'smooth' }));
}

function initFormLabels() {
  let generatedId = 0;
  const controls = document.querySelectorAll('input, select, textarea');

  controls.forEach(control => {
    if (control.type === 'hidden' || control.hasAttribute('aria-label') || control.hasAttribute('aria-labelledby')) return;
    if (control.labels && control.labels.length) return;

    const parentLabel = control.closest('label');
    const nearbyLabels = control.parentElement ? control.parentElement.querySelectorAll('label') : [];
    const label = parentLabel || (nearbyLabels.length === 1 ? nearbyLabels[0] : null);

    if (label) {
      if (!control.id) {
        do {
          generatedId += 1;
          control.id = `hrnexus-field-${generatedId}`;
        } while (document.querySelectorAll(`#${CSS.escape(control.id)}`).length > 1);
      }
      label.htmlFor = control.id;
      return;
    }

    const fallback = control.getAttribute('placeholder') || control.getAttribute('name') || control.getAttribute('title');
    if (fallback) control.setAttribute('aria-label', fallback);
  });
}

function init() {
  ThemeManager.init();
  SidebarManager.init();
  TopbarManager.init();
  TooltipManager.init();
  initFormLabels();
  initSearch();
  initTables();
  initKanban();
  initCharts();
  initBootstrapComponents();
  initScrollTop();

  window.HRNexus = { ThemeManager, SidebarManager, TopbarManager };
  console.log('[HRNexus] v4.0.0 ✓');
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', init);
} else {
  init();
}


})(window, document);
